<?php
require_once __DIR__.'/config/auth.php'; exigirPerfil(['Administrador','Técnico','Trabalhador']); require_once __DIR__.'/config/conexao.php';
$mensagem=''; $erro='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['acao']??'')==='chamado'){
  $id=(int)($_POST['id']??0); $status=$_POST['status']??'Aberto'; $resposta=trim($_POST['resposta']??'');
  $permitidos=['Aberto','Em atendimento','Aguardando cliente','Resolvido','Cancelado'];
  if(!$id || !in_array($status,$permitidos,true)) $erro='Dados inválidos para atualizar o chamado.';
  else { $st=$conn->prepare('UPDATE chamados_cliente SET status=?,resposta=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?'); $st->bind_param('ssi',$status,$resposta,$id); if($st->execute()) $mensagem='Chamado do cliente atualizado.'; else $erro='Não foi possível atualizar o chamado.'; }
}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['acao']??'')==='ordem'){
  $id=(int)($_POST['id']??0); $status=$_POST['status']??''; $diag=trim($_POST['diagnostico']??''); $serv=trim($_POST['servico_realizado']??'');
  $permitidos=['Aberta','Em andamento','Aguardando peça','Concluída','Entregue','Cancelada'];
  if(!$id || !in_array($status,$permitidos,true)) $erro='Dados inválidos para atualizar a ordem de serviço.';
  else { $st=$conn->prepare('UPDATE ordens_servico SET status=?,diagnostico=?,servico_realizado=? WHERE id=?'); $st->bind_param('sssi',$status,$diag,$serv,$id); if($st->execute()) $mensagem='Ordem de serviço atualizada.'; else $erro='Não foi possível atualizar a ordem.'; }
}
$chamados=$conn->query('SELECT cc.*,u.nome AS cliente_nome,u.email AS cliente_email FROM chamados_cliente cc JOIN usuarios u ON u.id=cc.usuario_id ORDER BY cc.criado_em DESC');
$ordens=$conn->query('SELECT os.*,c.nome AS cliente,e.tipo,e.marca,e.modelo,e.numero_serie,e.descricao AS especificacoes FROM ordens_servico os JOIN equipamentos e ON e.id=os.equipamento_id JOIN clientes c ON c.id=e.cliente_id ORDER BY os.data_abertura DESC,os.id DESC');
function statusClass($s){return in_array($s,['Concluída','Concluida','Entregue','Resolvido'],true)?'success':(in_array($s,['Cancelada','Cancelado','Aguardando peça'],true)?'warning':'');}
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atendimentos | HelpTech</title><link rel="stylesheet" href="css/style.css"><style>.case{background:#fff;border:1px solid #e5e9f0;border-radius:14px;padding:20px;margin:14px 0}.case-head{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.case form{margin-top:15px}.case textarea{min-height:75px}.section-title{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.specs{background:#f7f9fc;padding:12px 14px;border-radius:10px;margin:12px 0}.section-title h2{margin-bottom:4px}</style></head><body>
<header class="topbar"><a class="brand" href="dashboard.php"><span class="brand-mark">H</span>HelpTech</a><nav class="top-actions"><a href="dashboard.php">Painel técnico</a><span class="user-pill"><?=h($_SESSION['usuario_nome'])?></span><a href="logout.php">Sair ↗</a></nav></header>
<main class="container"><div class="page-title"><div><div class="eyebrow">Área técnica</div><h1>Atendimentos</h1><p class="subtitle">Chamados, especificações dos equipamentos e ordens de serviço em uma única tela.</p></div></div>
<?php if(isset($_GET['bloqueado'])):?><div class="alert error">O cadastro manual de novos atendimentos está desativado. Os clientes podem abrir chamados pela área do cliente.</div><?php endif;?><?php if($mensagem):?><div class="alert success"><?=h($mensagem)?></div><?php endif;?><?php if($erro):?><div class="alert error"><?=h($erro)?></div><?php endif;?>
<section class="panel"><div class="section-title"><div><h2>Chamados abertos pelos clientes</h2><p class="subtitle">Veja o problema e os detalhes do eletrônico informado pelo cliente.</p></div><span class="badge"><?= $chamados?(int)$chamados->num_rows:0 ?> chamados</span></div>
<?php if(!$chamados||!$chamados->num_rows):?><p class="empty">Nenhum chamado de cliente registrado.</p><?php else:while($c=$chamados->fetch_assoc()):?><article class="case"><div class="case-head"><div><h3>#<?= (int)$c['id']?> · <?=h($c['titulo'])?></h3><p class="subtitle">Cliente: <?=h($c['cliente_nome'])?> (<?=h($c['cliente_email'])?>) · <?=h(date('d/m/Y H:i',strtotime($c['criado_em'])))?></p></div><span class="badge <?=statusClass($c['status'])?>"><?=h($c['status'])?></span></div><div class="specs"><strong>Equipamento:</strong> <?=h(trim(($c['tipo_equipamento']??'Não informado').' '.($c['marca']??'').' '.($c['modelo']??'')))?><br><strong>Número de série:</strong> <?=h($c['numero_serie']?:'Não informado')?><br><strong>Estado físico:</strong> <?=h($c['estado_fisico']?:'Não informado')?><br><strong>Acessórios:</strong> <?=h($c['acessorios']?:'Não informado')?></div><p><strong>Prioridade:</strong> <?=h($c['prioridade'])?></p><p><strong>Problema:</strong><br><?=nl2br(h($c['descricao']))?></p><form method="post"><input type="hidden" name="acao" value="chamado"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><div class="form-grid"><div class="field"><label>Status</label><select name="status"><?php foreach(['Aberto','Em atendimento','Aguardando cliente','Resolvido','Cancelado'] as $s):?><option <?= $s===$c['status']?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></div><div class="field full"><label>Resposta / atualização para o cliente</label><textarea name="resposta" placeholder="Informe o diagnóstico, andamento ou orientação..."><?=h($c['resposta'])?></textarea></div></div><div class="form-actions"><button type="submit">Salvar chamado</button></div></form></article><?php endwhile;endif;?></section>
<section class="panel"><div class="section-title"><div><h2>Ordens de serviço</h2><p class="subtitle">Atualize o andamento das ordens existentes. O cadastro de novas ordens está desativado.</p></div><span class="badge"><?= $ordens?(int)$ordens->num_rows:0 ?> ordens</span></div>
<?php if(!$ordens||!$ordens->num_rows):?><p class="empty">Nenhuma ordem de serviço cadastrada.</p><?php else:while($o=$ordens->fetch_assoc()):?><article class="case"><div class="case-head"><div><h3>OS #<?= (int)$o['id']?> · <?=h($o['cliente'])?></h3><p class="subtitle"><?=h(trim($o['tipo'].' '.$o['marca'].' '.$o['modelo']))?> · Aberta em <?=h(date('d/m/Y',strtotime($o['data_abertura'])))?></p></div><span class="badge <?=statusClass($o['status'])?>"><?=h($o['status'])?></span></div><div class="specs"><strong>Especificações cadastradas:</strong> <?=h($o['especificacoes']?:'Não informado')?><br><strong>Número de série:</strong> <?=h($o['numero_serie']?:'Não informado')?><br><strong>Problema relatado:</strong> <?=nl2br(h($o['descricao_problema']))?></div><form method="post"><input type="hidden" name="acao" value="ordem"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><div class="form-grid"><div class="field"><label>Status da ordem</label><select name="status"><?php foreach(['Aberta','Em andamento','Aguardando peça','Concluída','Entregue','Cancelada'] as $s):?><option <?= $s===$o['status']?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></div><div class="field full"><label>Diagnóstico técnico</label><textarea name="diagnostico"><?=h($o['diagnostico'])?></textarea></div><div class="field full"><label>Serviço realizado</label><textarea name="servico_realizado"><?=h($o['servico_realizado'])?></textarea></div></div><div class="form-actions"><button type="submit">Atualizar ordem</button></div></form></article><?php endwhile;endif;?></section></main></body></html>
